def refs():
    return [{**s, "subject": "science", "locator": "細胞—組織—器官—器官系統—個體層次、植物根莖葉、動物組織與器官、功能分工與路徑判讀", "observedPattern": "公立學校公開生物試題常以層次排序、植物構造與動物器官系統題組，要求由組成與功能判斷層次；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-da-iv-3-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供多細胞組成層次、動植物器官與功能路徑的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "下列由小到大的組成層次排列何者正確？", {"A": "細胞→組織→器官→器官系統→個體", "B": "組織→細胞→器官系統→器官→個體", "C": "細胞→器官→組織→個體→器官系統", "D": "器官→組織→細胞→器官系統→個體"}, "相似細胞先形成組織，組織再協作形成器官，多個器官組成器官系統，最後整合為個體。", "先找每一層的組成單位，再依承接關係排列，不只依外觀大小猜測。", ["辨認最小的生物組成單位是細胞。", "確認相似細胞可形成組織。", "確認多種組織協作形成器官。", "將器官系統與完整個體放在後面。", "所以選 A。"], "easy"),
    make(2, "根毛細胞、根、莖、葉與整株植物的層次判斷，哪一項正確？", {"A": "根毛細胞是細胞，根是器官，根莖葉共同構成植物個體", "B": "根毛細胞是組織，根是器官系統", "C": "根、莖、葉都是同一個組織", "D": "整株植物只是放大的根毛細胞"}, "根毛細胞是單一細胞；根、莖、葉各由多種組織組成並完成不同功能，屬器官；共同合作形成植物個體。", "用組成數量與功能判斷層次，再確認器官如何合作成個體。", ["辨認根毛是單一細胞。", "判斷根由多種組織組成並執行吸收等功能。", "將根、莖、葉分類為植物器官。", "確認三者共同構成整株植物個體。", "所以選 A。"], "medium"),
    make(3, "木質部是根、莖或葉中的一部分，最合理的層次分類是？", {"A": "它是器官內的組織，負責和其他構造合作運輸水分與無機鹽", "B": "它是一個完整個體", "C": "它一定是器官系統", "D": "它是整株植物的單一細胞"}, "木質部由多種相關細胞組成並位於器官內，具有運輸功能，符合組織而非完整器官或系統。", "先問該結構由什麼組成、位於哪裡，再判斷它的功能層次。", ["確認木質部不是整株植物或獨立器官。", "找出它由許多相關細胞組成。", "辨認水分與無機鹽運輸是組織功能。", "說明它需和根、莖、葉其他組織合作。", "所以選 A。"], "medium"),
    make(4, "肺泡、肺與呼吸系統的關係，哪一項最正確？", {"A": "肺泡中的細胞與組織直接參與氣體交換，肺是器官，肺與其他器官共同形成呼吸系統", "B": "肺泡就是整個呼吸系統", "C": "肺是單一細胞放大形成的構造", "D": "呼吸系統只由肺一個器官組成且不需合作"}, "肺泡由細胞與組織形成交換表面，肺是由多種組織構成的器官，呼吸系統還包含其他合作器官。", "沿著氣體交換路徑由局部構造向上追蹤組成與合作。", ["先辨認直接進行交換的肺泡構造。", "確認肺泡由細胞與組織組成。", "把肺分類為器官。", "列出呼吸系統需整合的其他器官與功能。", "所以選 A。"], "medium"),
    make(5, "血液在人體層次判讀中為何不能直接當作器官？", {"A": "血液是由細胞與液體成分組成的組織，須和血管、心臟等器官合作完成運輸", "B": "血液是器官系統的另一個名稱", "C": "血液是人體的一顆巨大細胞", "D": "血液因為會流動，所以一定是個體"}, "血液包含多種細胞與基質，屬於組織；運輸功能還需循環器官系統的其他器官配合。", "不以流動或肉眼可見與否分類，改看組成與合作功能。", ["列出血液的細胞和液體成分。", "判斷多種細胞共同形成組織。", "確認它不是由多種組織形成的完整器官。", "說明血液需在血管與心臟等器官中運輸。", "所以選 A。"], "hard"),
    make(6, "同一功能路徑中，向上一個層次通常增加了什麼？", {"A": "更多結構的協作與更完整的整體功能，但不代表下層功能消失", "B": "只增加外觀大小，不增加任何功能", "C": "上層器官會取代所有細胞而不需分工", "D": "每向上一層就一定只剩一種細胞"}, "組成層次向上時，不同細胞、組織或器官的合作增加，形成更完整的功能；下層仍是基礎。", "比較每一層新增的組成者和任務，不把層次當成單純放大。", ["先寫出較低層次直接完成的功能。", "找出上層新增的組成者。", "說明新增者如何分工合作。", "確認下層構造仍存在並提供基礎功能。", "所以選 A。"], "easy"),
    make(7, "某廣告宣稱『看到一個肺泡細胞健康，就能證明整個呼吸系統健康』。問題主要在哪裡？", {"A": "把單一細胞證據過度外推到器官系統，忽略組織、器官協作與其他資料", "B": "細胞永遠不能提供任何健康資訊", "C": "呼吸系統其實只有一個細胞", "D": "器官系統與細胞是完全相同的層次"}, "單一細胞的影像或指標只能支持局部判斷，不能直接代表多層次器官系統的全部狀態。", "先標示證據所在層次，再檢查結論是否跨越了未測量的層次。", ["找出廣告實際觀察的是肺泡細胞。", "列出肺泡組織、肺與呼吸系統等上層。", "確認上層還有氣道、血流與神經等合作因素。", "把結論限制在局部，不宣稱整體健康。", "所以選 A。"], "hard"),
    make(8, "植物根部吸收的水分要送到葉片，哪條描述最能呈現多層次合作？", {"A": "根的組織吸收並運輸水，莖中的運輸組織傳遞，葉的組織利用水完成生命功能，三種器官共同合作", "B": "只要根毛細胞吸水，就不需要莖和葉", "C": "水會自行穿過整株植物，不需要任何組織", "D": "根、莖、葉其實都是同一種細胞"}, "水分運輸需由根、莖、葉的不同組織與器官串聯，任一層都不能單獨完成整條路徑。", "沿物質路徑標出直接作用者，再往上檢查器官間的接力。", ["找出根部負責吸收的細胞與組織。", "追蹤莖內運輸組織的傳遞功能。", "確認葉片組織使用水完成光合作用等功能。", "把根、莖、葉視為合作的器官而非同一細胞。", "所以選 A。"], "medium"),
    make(9, "下列哪項最能判斷某構造是器官，而不是只看大小？", {"A": "它由多種組織組成，能共同完成一項較完整的生理功能", "B": "它在圖片上畫得最大", "C": "它的名稱中含有『根』或『肺』", "D": "它位於個體外側就一定是器官"}, "器官的判準是多種組織的組成與協作功能，不是圖上大小、名稱或位置。", "先查組成，再查功能，最後用層次圖排除外觀直覺。", ["確認候選構造由哪些細胞或組織組成。", "判斷是否有多種組織合作。", "找出它完成的較完整生理功能。", "排除只靠名稱、位置或圖片大小的分類。", "所以選 A。"], "easy"),
    make(10, "比較多細胞生物組成層次時，最完整的作答方式是？", {"A": "說明每層的組成、直接功能、與上一層的合作及證據限制", "B": "只背出五個名詞，不必說明關係", "C": "只依大小排序，不需提功能", "D": "只用一個器官的照片代表整個個體"}, "層次判斷需要組成和功能的證據，也要說明跨層合作；只背名稱或只看大小無法解釋多細胞整合。", "用組成—功能—合作—限制四欄檢查答案。", ["列出細胞、組織、器官、系統與個體的順序。", "為每層填入直接完成的功能。", "補寫上層新增的合作關係。", "標示照片或單一證據不能支持的範圍。", "所以選 A。"], "medium"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
